package com.demo.models;

import org.owasp.html.PolicyFactory;
import org.owasp.html.Sanitizers;

public class WelcomeDTO {
    private String message;
    private static final PolicyFactory sanitizer = Sanitizers.FORMATTING.and(Sanitizers.LINKS);

    public WelcomeDTO(String message) {
        this.message = sanitizeMessage(message);
    }

    public String getMessage() {
        return message;
    }

    public void setMessage(String message) {
        this.message = sanitizeMessage(message);
    }

    private String sanitizeMessage(String message) {
        if (message == null) {
            return ""; // Or throw an exception, depending on requirements
        }
        return sanitizer.sanitize(message);
    }
}
